_EXPECTED_BLOB = ""

_EXTRACTS = {
    "A": "",
    "B": "",
}

_ENV = {"PATH": "/usr/local/bin:/usr/bin:/bin", "LANG": "C.UTF-8", "HOME": "/tmp", "PYTHONHASHSEED": "0"}
_REGIONS = ["North", "South", "West", "East"]
_SEGMENTS = ["commercial", "public"]
_ARTIFACTS = [
    "region_North.json",
    "region_South.json",
    "region_West.json",
    "region_East.json",
    "segment_commercial.json",
    "segment_public.json",
    "summary.json",
    "policy_audit.json",
    "data_quality.json",
]
_OUTCOMES = {"full", "partial", "zero", "declined"}
_REASONS = {"AWARD_FULL", "LEVEL_BOUND", "SUPPLY_EXHAUSTED", "CEILING_ZERO"}
_SPINE = ["ledger_spine", "ledger_award", "cells"]
_CACHE = {}
_LOCK = threading.Lock()


def _prefix():
    """Drop privileges where the image allows it, with the group name it actually carries."""
    if "prefix" in _CACHE:
        return _CACHE["prefix"]
    found = []
    if shutil.which("setpriv"):
        for group in ("nogroup", "nobody"):
            trial = ["setpriv", "--reuid=nobody", "--regid=" + group, "--clear-groups", "true"]
            try:
                probe = subprocess.run(trial, stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30)
            except Exception:
                continue
            if probe.returncode == 0:
                found = trial[:-1]
                break
    _CACHE["prefix"] = found
    return found


def _safe(action):
    try:
        return bool(action())
    except Exception:
        return False


def _expected():
    if "expected" not in _CACHE:
        _CACHE["expected"] = json.loads(zlib.decompress(base64.b64decode(_EXPECTED_BLOB)))
    return _CACHE["expected"]


def _digest(lines):
    return hashlib.sha256("\n".join(lines).encode()).hexdigest()


def _whole(value):
    if isinstance(value, bool) or not isinstance(value, int):
        return "invalid"
    return "%d" % value


def _text(value):
    if not isinstance(value, str):
        return "invalid"
    return value


def _views(out: Path):
    families = {name: [] for name in [
        "ledger_spine",
        "ledger_award",
        "ledger_entitlement",
        "ledger_outcome",
        "ledger_lot",
        "ledger_order",
        "cells",
        "segment_regions",
        "segment_rounds",
        "summary_core",
        "summary_lists",
        "audit_rules",
        "audit_tallies",
        "quality_rejects",
        "quality_counted",
        "quality_sources",
    ]}
    for region in _REGIONS:
        document = json.loads((out / ("region_%s.json" % region)).read_text())
        for index, row in enumerate(document["ledger"]):
            stem = "%s|%s|%s" % (region, _text(row["round"]), _text(row["block"]))
            families["ledger_spine"].append(
                "%s|%s|%s|%s"
                % (stem, _whole(row["awarded_to_date"]), _whole(row["deferred_to_date"]), _whole(row["carry_forward_doses"]))
            )
            families["ledger_award"].append(
                "%s|%s|%s|%s"
                % (stem, _whole(row["awarded_doses"]), _whole(row["deferred_doses"]), _whole(row["claimable_doses"]))
            )
            families["ledger_entitlement"].append(
                "%s|%s|%s|%s"
                % (stem, _whole(row["entitlement_doses"]), _whole(row["carried_claim_doses"]), _whole(row["tier"]))
            )
            families["ledger_outcome"].append("%s|%s|%s" % (stem, _text(row["outcome"]), _text(row["reason"])))
            families["ledger_lot"].append("%s|%s|%s" % (stem, _text(row["served_lot"]), _whole(row["substitution_hops"])))
            families["ledger_order"].append(
                "%s|%d|%s|%s|%s" % (region, index, _text(row["round"]), _text(row["block"]), _whole(row["tier"]))
            )
        for cell in document["cells"]:
            families["cells"].append(
                "%s|%s|%s|%s|%s|%s|%s|%s|%s|%s"
                % (
                    region,
                    _text(cell["round"]),
                    _whole(cell["available_doses"]),
                    _whole(cell["claimable_doses"]),
                    _whole(cell["awarded_doses"]),
                    _whole(cell["waterline"]),
                    _whole(cell["binding_tier"]),
                    _whole(cell["surplus_doses"]),
                    _whole(cell["cleared_balances"]),
                    _whole(cell["written_off_doses"]),
                )
            )
    for segment in _SEGMENTS:
        document = json.loads((out / ("segment_%s.json" % segment)).read_text())
        for entry in document["regions"]:
            families["segment_regions"].append(
                "%s|%s|%s|%s|%s|%s|%s|%s|%s|%s|%s"
                % (
                    segment,
                    _text(entry["region"]),
                    _whole(entry["claims"]),
                    _whole(entry["awarded_doses"]),
                    _whole(entry["claimable_doses"]),
                    _whole(entry["deferred_doses"]),
                    _whole(entry["carry_forward_doses"]),
                    _whole(entry["full"]),
                    _whole(entry["partial"]),
                    _whole(entry["zero"]),
                    _whole(entry["declined"]),
                )
            )
        for entry in document["rounds"]:
            families["segment_rounds"].append(
                "%s|%s|%s|%s|%s"
                % (
                    segment,
                    _text(entry["round"]),
                    _whole(entry["claims"]),
                    _whole(entry["awarded_doses"]),
                    _whole(entry["deferred_doses"]),
                )
            )
    summary = json.loads((out / "summary.json").read_text())
    for key in sorted(summary):
        value = summary[key]
        if isinstance(value, bool) or not isinstance(value, int):
            continue
        families["summary_core"].append("%s|%s" % (key, _whole(value)))
    families["summary_lists"].append("live|%s" % ",".join(summary["live_rounds"]))
    families["summary_lists"].append("skipped|%s" % ",".join(summary["skipped_rounds"]))
    for entry in summary["regions"]:
        families["summary_lists"].append(
            "region|%s|%s|%s|%s"
            % (_text(entry["region"]), _whole(entry["claims"]), _whole(entry["awarded_doses"]), _whole(entry["deferred_doses"]))
        )
    for entry in summary["segments"]:
        families["summary_lists"].append(
            "segment|%s|%s|%s" % (_text(entry["segment"]), _whole(entry["claims"]), _whole(entry["awarded_doses"]))
        )
    audit = json.loads((out / "policy_audit.json").read_text())
    families["audit_rules"].append("before|%s" % _text(audit["governing_source"]["before_cutover"]))
    families["audit_rules"].append("from|%s" % _text(audit["governing_source"]["from_cutover"]))
    families["audit_rules"].append("scope|%s" % _text(audit["balance_clearance_scope"]))
    for key in sorted(audit["binding_tiers"]):
        families["audit_rules"].append("binding|%s|%s" % (key, _whole(audit["binding_tiers"][key])))
    for entry in audit["clearing_rounds"]:
        families["audit_rules"].append("clearing|%s|%s" % (_text(entry["region"]), ",".join(entry["rounds"])))
    for key in sorted(audit):
        value = audit[key]
        if isinstance(value, bool):
            continue
        if isinstance(value, int):
            families["audit_tallies"].append("%s|%s" % (key, _whole(value)))
        elif isinstance(value, dict) and key in ("alias_hops", "substituted_lots"):
            for inner in sorted(value):
                families["audit_tallies"].append("%s|%s|%s" % (key, inner, _whole(value[inner])))
    quality = json.loads((out / "data_quality.json").read_text())
    for key in sorted(quality["rejects"]):
        families["quality_rejects"].append("%s|%s" % (key, _whole(quality["rejects"][key])))
    for key in sorted(quality["counted"]):
        families["quality_counted"].append("%s|%s" % (key, _whole(quality["counted"][key])))
    for key in sorted(quality["source_rows"]):
        families["quality_sources"].append("%s|%s" % (key, _whole(quality["source_rows"][key])))
    return families


def _digests(out: Path):
    return {name: _digest(lines) for name, lines in _views(out).items()}


def _matches(out, corpus, names):
    if out is None:
        return False
    marks = _digests(out)
    wanted = _expected()[corpus]["digests"]
    return all(marks.get(name) == wanted[name] for name in names)


def _module(workspace):
    return Path(workspace) / "out" / "derive_report.py"


def _delivered(workspace):
    return Path(workspace) / "out"


def _source(workspace):
    return _module(workspace).read_text(errors="replace")


def _complete(out):
    return out is not None and all((out / name).is_file() for name in _ARTIFACTS)


def _unpack(corpus, target: Path):
    raw = zlib.decompress(base64.b64decode(_EXTRACTS[corpus]))
    target.mkdir(parents=True, exist_ok=True)
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r") as archive:
        archive.extractall(target)


def _shuffle_rows(directory: Path):
    for item in sorted(directory.iterdir()):
        if item.suffix not in (".csv", ".tsv", ".jsonl"):
            continue
        lines = item.read_text().split("\n")
        tail = lines[-1] == ""
        if tail:
            lines = lines[:-1]
        head = []
        while lines and lines[0].startswith("#"):
            head.append(lines.pop(0))
        if item.suffix in (".csv", ".tsv") and lines:
            head.append(lines.pop(0))
        half = len(lines) // 2
        body = lines[half:] + lines[:half]
        text = "\n".join(head + body)
        if tail:
            text = text + "\n"
        item.write_text(text)


def _survivors():
    found = []
    for entry in Path("/proc").iterdir():
        if not entry.name.isdigit():
            continue
        try:
            status = (entry / "status").read_text()
        except Exception:
            continue
        fields = dict(line.split(":", 1) for line in status.splitlines() if ":" in line)
        uid = fields.get("Uid", "").split()
        state = fields.get("State", "").split()
        if uid and uid[0] == "65534" and state and state[0] != "Z":
            found.append(entry.name)
    return found


def _reap(process):
    try:
        os.killpg(process.pid, signal.SIGKILL)
    except Exception:
        pass
    try:
        process.wait(timeout=30)
    except Exception:
        pass
    if not _prefix():
        return
    # kill(-1) from the unprivileged identity signals every process of that identity in one
    # kernel pass, so a descendant that keeps forking cannot outrun it.
    sweep = [*_prefix(), sys.executable, "-I", "-c", "import os, signal\nos.kill(-1, signal.SIGKILL)"]
    for _ in range(20):
        if not _survivors():
            return
        try:
            subprocess.run(sweep, env=dict(_ENV), stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=30)
        except Exception:
            pass


def _paths(value, prefix=""):
    found = set()
    if isinstance(value, dict):
        for key, item in value.items():
            here = prefix + "/" + key
            found.add(here)
            found |= _paths(item, here)
    elif isinstance(value, list):
        for item in value:
            found |= _paths(item, prefix + "/*")
    return found


def _shape_ok(out, corpus):
    wanted = _expected()[corpus]["shape"]
    for name in _ARTIFACTS:
        if sorted(_paths(json.loads((out / name).read_text()))) != wanted[name]:
            return False
    return True


def _orders_ok(out, corpus):
    quality = json.loads((out / "data_quality.json").read_text())
    wanted = _expected()[corpus]["orders"]
    return all(list(quality[key]) == wanted[key] for key in wanted)


def _bytes(out):
    return {name: hashlib.sha256((out / name).read_bytes()).hexdigest() for name in _ARTIFACTS}


def _hardcoded(workspace):
    if not _module(workspace).is_file():
        return False
    numbers, strings = _literals(workspace)
    scalars = _expected()["shipped"]["scalars"]
    marks = {int(scalars[key]) for key in scalars}
    if marks & numbers:
        return True
    wanted = set(_expected()["shipped"]["digests"].values())
    return any(value in wanted for value in strings)


def _embedded(workspace):
    if not _module(workspace).is_file():
        return False
    marks = ("REQ-0", "CRT-0", "AMD-0", "BLK-0", "LOT-1")
    numbers, strings = _literals(workspace)
    for value in strings:
        if len(value) > 4000 and sum(value.count(mark) for mark in marks) >= 5:
            return True
    text = _source(workspace)
    return sum(text.count(mark) for mark in marks) > 40


def _independent(workspace):
    first = _run(workspace, "A")
    second = _run(workspace, "B")
    if first["code"] != 0 or second["code"] != 0:
        return False
    if not _complete(first["out"]) or not _complete(second["out"]):
        return False
    return _digests(first["out"])["ledger_spine"] == _digests(second["out"])["ledger_spine"]


def _unsteady(workspace):
    first = _run(workspace, "A")
    again = _run(workspace, "A_again")
    if first["code"] != 0 or again["code"] != 0:
        return False
    if not _complete(first["out"]) or not _complete(again["out"]):
        return False
    return _bytes(first["out"]) != _bytes(again["out"])


def _run(workspace, tag):
    with _LOCK:
        return _execute(workspace, tag)


def _execute(workspace, tag):
    if tag in _CACHE:
        return _CACHE[tag]
    corpus = tag.split("_")[0]
    blank = {"code": -1, "out": None, "data": None, "before": {}, "after": {}}
    program = _module(workspace)
    if not program.is_file():
        _CACHE[tag] = blank
        return blank
    room = Path(tempfile.mkdtemp(prefix="hold_"))
    folder = room / ("corpus_" + tag if tag.endswith("named") else "data")
    _unpack(corpus, folder)
    if tag.endswith("perm"):
        _shuffle_rows(folder)
    if tag.endswith("missing"):
        victim = folder / "lot_register_p1.csv"
        if victim.is_file():
            victim.unlink()
    copy = room / "delivered.py"
    shutil.copy2(program, copy)
    os.chmod(copy, 0o755)
    before = {}
    for item in sorted(folder.iterdir()):
        before[item.name] = hashlib.sha256(item.read_bytes()).hexdigest()
    out = room / "out"
    out.mkdir()
    for target in (room, folder, out):
        os.chmod(target, 0o777)
    command = [*_prefix(), sys.executable, "-I", str(copy), "--data", str(folder), "--out", str(out)]
    try:
        process = subprocess.Popen(
            command,
            cwd=str(room),
            env=dict(_ENV),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            start_new_session=True,
        )
    except OSError:
        _CACHE[tag] = blank
        return blank
    try:
        process.communicate(timeout=300)
        code = process.returncode
    except subprocess.TimeoutExpired:
        code = -1
    finally:
        _reap(process)
        os.chmod(room, 0o700)
    after = {}
    for item in sorted(folder.iterdir()):
        after[item.name] = hashlib.sha256(item.read_bytes()).hexdigest()
    answer = {"code": code, "out": out, "data": folder, "before": before, "after": after}
    _CACHE[tag] = answer
    return answer


def _literals(workspace):
    tree = ast.parse(_source(workspace))
    numbers = set()
    strings = []
    for node in ast.walk(tree):
        if isinstance(node, ast.Constant):
            if isinstance(node.value, bool):
                continue
            if isinstance(node.value, int):
                numbers.add(node.value)
            elif isinstance(node.value, str):
                strings.append(node.value)
    return numbers, strings


