@criterion(description="Permuting the record rows of an unseen extract leaves every delivered document the same.")
def row_order_permutation_changes_nothing(workspace: Path) -> bool:
    def body():
        plain = _run(workspace, "A")
        mixed = _run(workspace, "A_perm")
        if plain["code"] != 0 or mixed["code"] != 0:
            return False
        if not _complete(plain["out"]) or not _complete(mixed["out"]):
            return False
        if _digests(plain["out"]) != _digests(mixed["out"]):
            return False
        return _matches(mixed["out"], "A", sorted(_expected()["A"]["digests"]))

    return _safe(body)


@criterion(description="The ledgers, the segment rollups, the cells and the summary agree with each other on every award and claim count.")
def cross_artifact_identity_triangle_holds(workspace: Path) -> bool:
    def work():
        out = _delivered(workspace)
        if not _complete(out):
            return False
        summary = json.loads((out / "summary.json").read_text())
        segments = {name: json.loads((out / ("segment_%s.json" % name)).read_text()) for name in _SEGMENTS}
        totals = {}
        claims = {}
        deferred = {}
        for region in _REGIONS:
            document = json.loads((out / ("region_%s.json" % region)).read_text())
            rows = document["ledger"]
            totals[region] = sum(row["awarded_doses"] for row in rows)
            deferred[region] = sum(row["deferred_doses"] for row in rows)
            claims[region] = len(rows)
            if sum(cell["awarded_doses"] for cell in document["cells"]) != totals[region]:
                return False
            running = {}
            carried = {}
            for row in rows:
                block = row["block"]
                running[block] = running.get(block, 0) + row["awarded_doses"]
                carried[block] = carried.get(block, 0) + row["deferred_doses"]
                if row["awarded_to_date"] != running[block] or row["deferred_to_date"] != carried[block]:
                    return False
                if row["claimable_doses"] != row["entitlement_doses"] + row["carried_claim_doses"]:
                    return False
                if row["deferred_doses"] != row["claimable_doses"] - row["awarded_doses"]:
                    return False
        for entry in summary["regions"]:
            if entry["awarded_doses"] != totals[entry["region"]] or entry["claims"] != claims[entry["region"]]:
                return False
            if entry["deferred_doses"] != deferred[entry["region"]]:
                return False
        if summary["awarded_doses"] != sum(totals.values()) or summary["claims_settled"] != sum(claims.values()):
            return False
        for region in _REGIONS:
            share = 0
            heads = 0
            for name in _SEGMENTS:
                for entry in segments[name]["regions"]:
                    if entry["region"] == region:
                        share += entry["awarded_doses"]
                        heads += entry["claims"]
            if share != totals[region] or heads != claims[region]:
                return False
        for name in _SEGMENTS:
            rounds = sum(entry["awarded_doses"] for entry in segments[name]["rounds"])
            regions = sum(entry["awarded_doses"] for entry in segments[name]["regions"])
            if rounds != regions:
                return False
            for entry in summary["segments"]:
                if entry["segment"] == name and entry["awarded_doses"] != regions:
                    return False
        return True


    def body():
        try:
            return work()
        except Exception:
            return False
    return _safe(body)


